const { date } = $input.first().json.body;
if (!date) return [{ json: { error: 'date required', slots: [], date: null } }];

const d = new Date(date + 'T12:00:00Z');
if (d.getDay() === 0 || d.getDay() === 6) {
  return [{ json: { date, slots: [], error: 'Closed on weekends' } }];
}

const slots = [];
for (let h = 9; h < 18; h++) {
  for (let m = 0; m < 60; m += 30) {
    const t = `${String(h).padStart(2,'0')}:${String(m).padStart(2,'0')}`;
    slots.push({ time: t, datetime: `${date}T${t}:00` });
  }
}
return [{ json: { date, slots } }];

const items = $input.all();
const slotsItem = items.find(i => Array.isArray(i.json.slots));
if (!slotsItem) return [{ json: { error: 'No slot data', available_slots: [] } }];

const { date, slots, error } = slotsItem.json;
if (error || !slots.length) return [{ json: { date, available_slots: [], error } }];

const events = items.filter(i => i.json.id && i.json.start).map(i => i.json);
const OFF = '-04:00';

const available = slots.filter(slot => {
  const s = new Date(slot.datetime + OFF);
  const e = new Date(s.getTime() + 1800000);
  const count = events.filter(ev => {
    const es = new Date(ev.start.dateTime || ev.start.date + 'T00:00:00' + OFF);
    const ee = new Date(ev.end.dateTime || ev.end.date + 'T23:59:59' + OFF);
    return es < e && ee > s;
  }).length;
  return count < 2;
});

return [{ json: { date, available_slots: available.map(s => s.time) } }];
